INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 11, 10, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", "", 111031, "", "", 13020019, "", 302);
INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 93, "", "", "", 5, "", "", 13020020, "", 302);
