INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 11, 10, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", 111031, "", "", 13020023, "", 302);
INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 91, "", "", "", 0, "", "", 13020024, "", 302);
