INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 11, 10, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", "", 111031, "", "", 13020026, "", 302);
INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 91, "", 1, "", 0, "", "", 13020027, "", 302);
INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 11, 10, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", 111031, "", "", 13020028, "", 302);
INSERT INTO `v1_25272edae4732c1b61c1e1927716da08a7f6dda7187b1a80f4e29a46f545b1d0` VALUES ("", 91, "", 1, "", 0, "", "", 13020029, "", 302);
